// Generated by npm run build. Edit scripts/service-worker.template.js instead.
const BUILD_ID = __BUILD_ID__;
const PRECACHE_URLS = __PRECACHE_URLS__;
const APP_PREFIX = "baby-feeding-tracker-";
const SCOPE_PREFIX =
  APP_PREFIX +
  encodeURIComponent(new URL(self.registration.scope).pathname) +
  "-";
const CACHE_NAME = SCOPE_PREFIX + BUILD_ID;
const INDEX_URL = new URL("./index.html", self.registration.scope).href;
const PRECACHE_SET = new Set(
  PRECACHE_URLS.map((path) => new URL(path, self.registration.scope).href),
);

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      // Fetch everything before writing anything. A broken or partial deployment must
      // fail installation and leave the previous worker and its cache available.
      const entries = await Promise.all(
        PRECACHE_URLS.map(async (path) => {
          const request = new Request(
            new URL(path, self.registration.scope).href,
            { cache: "reload", credentials: "same-origin" },
          );
          const response = await fetch(request);
          if (!response.ok || response.type === "opaque")
            throw new Error("Required offline file unavailable: " + path);
          if (request.url === INDEX_URL) {
            const html = await response.clone().text();
            if (
              !html.includes(
                '<meta name="app-build" content="' + BUILD_ID + '">',
              )
            ) {
              throw new Error(
                "App files belong to different builds. Keeping previous installation.",
              );
            }
          }
          return [request, response];
        }),
      );
      try {
        const cache = await caches.open(CACHE_NAME);
        await Promise.all(
          entries.map(([request, response]) => cache.put(request, response)),
        );
      } catch (error) {
        await caches.delete(CACHE_NAME);
        throw error;
      }
    })(),
  );
  // Updates wait until a user selects Update, or all old app tabs are closed.
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names
          .filter(
            (name) =>
              name !== CACHE_NAME &&
              (name.startsWith(SCOPE_PREFIX) ||
                /^baby-feeding-tracker-v\d+$/.test(name)),
          )
          .map((name) => caches.delete(name)),
      );
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);
  const scope = new URL(self.registration.scope);
  if (
    request.method !== "GET" ||
    url.origin !== scope.origin ||
    !url.pathname.startsWith(scope.pathname)
  )
    return;
  if (request.mode === "navigate") {
    // Each worker always serves the HTML matching its own bundled assets.
    // Query-string shortcuts (e.g. ?view=history) use that same app shell.
    event.respondWith(
      (async () => {
        const cache = await caches.open(CACHE_NAME);
        return (await cache.match(INDEX_URL)) || fetch(request);
      })(),
    );
    return;
  }
  if (PRECACHE_SET.has(url.href)) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(CACHE_NAME);
        return (await cache.match(request)) || fetch(request);
      })(),
    );
  }
  // Other resources use normal browser networking. Never turn a missing script,
  // image, or external request into an HTML response, and never cache user data.
});

self.addEventListener("message", (event) => {
  if (event.data?.type === "SKIP_WAITING") event.waitUntil(self.skipWaiting());
});
